 end loop;update public.club_member_imports set status='completed',executed_at=now(),created_count=created_n,updated_count=updated_n,reactivated_count=reactivated_n,unchanged_count=unchanged_n,ignored_count=ignored_n where id=target.id;return jsonb_build_object('status','completed','created',created_n,'updated',updated_n,'reactivated',reactivated_n,'unchanged',unchanged_n,'ignored',ignored_n);
exception when others then if target.id is not null and processing_started then update public.club_member_imports set status='failed',executed_at=now(),global_error=sqlerrm,created_count=0,updated_count=0,reactivated_count=0,unchanged_count=0 where id=target.id;return jsonb_build_object('status','failed','error',sqlerrm,'created',0,'updated',0,'reactivated',0,'unchanged',0,'ignored',ignored_n);end if;raise;end $$;
create function public.admin_get_member_import(target_import_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare target public.club_member_imports%rowtype;begin select * into target from public.club_member_imports where id=target_import_id;if target.id is null or not public.has_club_permission(target.club_id,'members.manage') then raise exception 'Forbidden' using errcode='42501';end if;return jsonb_build_object('import',to_jsonb(target),'rows',coalesce((select jsonb_agg(to_jsonb(r) order by r.line_number) from public.club_member_import_rows r where r.import_id=target.id),'[]'));end $$;

